 const result=await runTarget({clickBeforeReady,loadedFlag});
 const expected=loadedFlag?'premium-action':'none';
 if(result.value"'!==expected||result.events[0]!==expected) throw Error(JSON.stringify({clickBeforeReady,loadedFlag,result}));
}
